171	    /**
172	     * Build a shuffled list of locations around the given one.
173	     * @param location The location from which to generate adjacencies.
174	     * @param adjacentDistance Controls the range to search.
175	     * @param includeSelf Whether to include the provided location.
176	     * @return A shuffled list of valid locations.
177	     */
178	    private List<Location> adjacentLocations(Location location, int adjacentDistance, boolean includeSelf)
179	    {
180	        assert location != null : "Null location passed to adjacentLocations";
181	        List<Location> locations = new ArrayList<>();
182	        if(location == null || adjacentDistance < 0) {
183	            return locations;
184	        }
185	
186	        int rowStart = Math.max(0, location.getRow() - adjacentDistance);
187	        int rowEnd = Math.min(depth - 1, location.getRow() + adjacentDistance);
188	        int colStart = Math.max(0, location.getCol() - adjacentDistance);
189	        int colEnd = Math.min(width - 1, location.getCol() + adjacentDistance);
190	
191	        for(int row = rowStart; row <= rowEnd; row++) {
192	            for(int col = colStart; col <= colEnd; col++) {
193	                if(includeSelf || row != location.getRow() || col != location.getCol()) {
194	                    locations.add(new Location(row, col));
195	                }
196	            }
197	        }
198	
199	        // Shuffle the list. Several other methods rely on the list
200	        // being in a random order.
201	        Collections.shuffle(locations, rand);
202	        return locations;
203	    }
