240	    public List<Object> getAllObjectAt(Location location, int adjacentDistance)
241	    {
242	        List<Object> adjacentObjectList = new ArrayList<>();
243	
244	        for(Location where : adjacentLocationsIncludingSelf(location, adjacentDistance)) {
245	            Object adjacentObject = getObjectAt(where);
246	            if(adjacentObject != null) {
247	                adjacentObjectList.add(adjacentObject);
